insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values

  -- ── TEMA 1: ep9-familia (8 lección + 8 banco + 3 examen) ──
  ('ep9-familia-01', 'ep9-familia', 1, 'elegir', $j${"frase":"My mother's sister is my ___.","opciones":["aunt","cousin","niece"],"correcta":0,"es":"La hermana de mi mamá es mi tía.","explicacion":"aunt = tía."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-02', 'ep9-familia', 2, 'elegir', $j${"frase":"My father's brother is my ___.","opciones":["uncle","nephew","cousin"],"correcta":0,"es":"El hermano de mi papá es mi tío.","explicacion":"uncle = tío."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-03', 'ep9-familia', 3, 'elegir', $j${"frase":"My aunt's son is my ___.","opciones":["nephew","cousin","brother"],"correcta":1,"es":"El hijo de mi tía es mi primo.","explicacion":"cousin = primo/prima."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-04', 'ep9-familia', 4, 'emparejar', $j${"pares":[["grandmother","abuela"],["grandfather","abuelo"],["nephew","sobrino"],["niece","sobrina"]],"es":"","explicacion":"Miembros de la familia extendida."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-05', 'ep9-familia', 5, 'escribir', $j${"respuestas":["my sister has two children","my sister has two children."],"mostrar":"My sister has two children.","es":"Mi hermana tiene dos hijos.","explicacion":"children = hijos (plural irregular de child)."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-06', 'ep9-familia', 6, 'ordenar', $j${"frase":"My grandparents live in a small town .","es":"Mis abuelos viven en un pueblo pequeño.","explicacion":"grandparents = abuelos."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-07', 'ep9-familia', 7, 'escuchar', $j${"opciones":["My uncle is a doctor.","My aunt is a doctor.","My cousin is a doctor."],"correcta":0,"audio":"My uncle is a doctor.","es":"Mi tío es doctor.","explicacion":"uncle = tío."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('ep9-familia-08', 'ep9-familia', 8, 'dictado', $j${"audio":"She has three brothers and one sister.","respuestas":["she has three brothers and one sister","she has three brothers and one sister."],"mostrar":"She has three brothers and one sister.","es":"Ella tiene tres hermanos y una hermana.","explicacion":"brothers = hermanos; sister = hermana."}$j$::jsonb, 'ep9-familia', 'estudio', false),
  ('banco-ep9-familia-01', 'banco-ep9', 1, 'comprension', $j${"modo":"leer","lineas":[{"en":"Maria: This is a photo of my family. The woman on the left is my grandmother.","es":"María: Esta es una foto de mi familia. La mujer a la izquierda es mi abuela."},{"en":"Tom: She looks very young!","es":"Tom: ¡Se ve muy joven!"}],"pregunta":"Who is the woman on the left?","pregunta_es":"¿Quién es la mujer a la izquierda?","opciones":["Maria's grandmother","Maria's mother","Maria's aunt"],"correcta":0,"explicacion":"grandmother = abuela."}$j$::jsonb, 'ep9-familia', 'input', false),
  ('banco-ep9-familia-02', 'banco-ep9', 2, 'comprension', $j${"modo":"leer","lineas":[{"en":"Pedro: How many cousins do you have?","es":"Pedro: ¿Cuántos primos tienes?"},{"en":"Ana: I have six cousins. Three from my mother's side and three from my father's side.","es":"Ana: Tengo seis primos. Tres del lado de mi mamá y tres del lado de mi papá."}],"pregunta":"How many cousins does Ana have?","pregunta_es":"¿Cuántos primos tiene Ana?","opciones":["Six","Three","Nine"],"correcta":0,"explicacion":"six cousins = seis primos."}$j$::jsonb, 'ep9-familia', 'input', false),
  ('banco-ep9-familia-03', 'banco-ep9', 3, 'decir', $j${"es":"Mi abuela tiene ochenta años.","respuestas":["my grandmother is eighty years old","my grandmother is eighty years old."],"mostrar":"My grandmother is eighty years old.","explicacion":"grandmother = abuela."}$j$::jsonb, 'ep9-familia', 'output', false),
  ('banco-ep9-familia-04', 'banco-ep9', 4, 'decir', $j${"es":"Tengo dos hermanos y una hermana.","respuestas":["i have two brothers and one sister","i have two brothers and a sister"],"mostrar":"I have two brothers and one sister.","explicacion":"brothers = hermanos."}$j$::jsonb, 'ep9-familia', 'output', false),
  ('banco-ep9-familia-05', 'banco-ep9', 5, 'libre', $j${"pregunta":"Describe your family. How many brothers, sisters, cousins do you have? Who is the eldest?","pregunta_es":"Describe tu familia. ¿Cuántos hermanos, hermanas, primos tienes? ¿Quién es el mayor?","ejemplo":"I have one brother. He is older than me. I have four cousins."}$j$::jsonb, 'ep9-familia', 'output', false),
